// Runs after `prisma generate`. Writes the barrel file that lets
// callers `import { PrismaClient } from '@/generated/prisma'` instead
// of the longer `@/generated/prisma/client`.
//
// Prisma 7's `prisma-client` generator does not emit an index file by
// default; this script restores the canonical import path.

import { writeFileSync } from "node:fs";
import { resolve } from "node:path";

const target = resolve("src/generated/prisma/index.ts");
const contents = [
  "// Auto-generated by scripts/post-prisma-generate.mjs. Do not edit by hand.",
  "// Re-exports the Prisma 7 client so `@/generated/prisma` resolves to the",
  "// PrismaClient class, types, $Enums, and Prisma namespace.",
  "export * from './client';",
  "",
].join("\n");

writeFileSync(target, contents, "utf8");
console.log(`barrel: wrote ${target}`);
